--  DDL for View V_CATEGORY_LOV
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ODAF"."V_CATEGORY_LOV" ("CATEGORY_ID_HEX", "CATEGORY_CODE", "CATEGORY_NAME", "ACTIVE_FLAG") AS 
  SELECT
    RAWTOHEX(CATEGORY_ID) AS CATEGORY_ID_HEX,
    CATEGORY_CODE,
    CATEGORY_NAME,
    ACTIVE_FLAG
FROM M_CATEGORY
WHERE ACTIVE_FLAG = 1
ORDER BY CATEGORY_NAME
;
